#include <iostream>
#include <vector>
#include <ranges>

int main() {
    using namespace std;
    int N;
    cin >> N;

    vector<int> A(N);
    for (auto&& a : A) {
        cin >> a;
        --a; // 0-indexed にしておく
    }

    vector<int> ans(N);
    for (int i : views::iota(0, N) | views::reverse) { // 降順に、最後に到着するマスを求める
        if (i == A[i]) { // はじめから動かないなら
            ans[i] = i; // そのマスが答え
        } else { // 動くなら
            ans[i] = ans[A[i]]; // 動いた先のマスから始めたときの結果が答え
        }
    }

    for (int a : ans) {
        // 1-indexed に直して出力
        cout << a + 1 << " ";
    }
    cout << endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <ranges>

int main() {
    using namespace std;
    int N;
    cin >> N;

    vector<int> A(N);
    for (auto&& a : A) {
        cin >> a;
        --a; // 0-indexed にしておく
    }

    // 10 倍するのを 100 回繰り返す
    for (int i = 0; i < 100; ++i) {
        vector<int> tmp(N);
        for (int j : views::iota(0, N)) {
            tmp[j] = A[A[A[A[A[A[A[A[A[A[j]]]]]]]]]];
        }
        A = tmp;
    }

    // 1-indexed に直して出力
    for (const auto a : A) {
        cout << a + 1 << " ";
    }
    cout << endl;

    return 0;
}

#include <iostream>
#include <vector>
#include <ranges>

int main() {
    using namespace std;
    int N;
    cin >> N;

    vector<int> A(N);
    for (auto&& a : A) {
        cin >> a;
        --a; // 0-indexed にしておく
    }

    // 答えを順番に求める
    for (int ans : views::iota(0, N)) {
        while (ans != A[ans])
            ans = A[ans] = A[A[ans]]; // 経路圧縮をしながら探索
        cout << ans + 1 << " "; // 1-indexed に直して出力
    }
    cout << endl;

    return 0;
}
